// Generated by scripts/prepare-handout.py from student materials; do not edit.
(() => {
  const files = {"lecture_note_05.md": "", "lesson05.py": "", "lesson05.R": ""};
  const urls = new Map(Object.entries(files).map(([name, encoded]) => {
    const bytes = Uint8Array.from(atob(encoded), char => char.charCodeAt(0));
    const type = name.endsWith('.md') ? 'text/markdown;charset=utf-8' : 'text/plain;charset=utf-8';
    return [name, URL.createObjectURL(new Blob([bytes], {type}))];
  }));
  function prepare(link) {
    const url = urls.get(link?.getAttribute('download'));
    if (url) link.href = url;
  }
  document.querySelectorAll('a[download]').forEach(prepare);
  // Reveal Markdown may create the links after this script runs.
  document.addEventListener('click', event => {
    prepare(event.target.closest?.('a[download]'));
  });
})();
